WITH mun AS (SELECT * FROM UNNEST(['2930766','2918100','2900355','2929701','2926509','2909208']) AS id_municipio),car AS (SELECT REPLACE(id_imovel,'-','') id_car_norm,id_imovel,id_municipio,area FROM `basedosdados.br_sfb_sicar.area_imovel` JOIN mun USING(id_municipio) WHERE data_extracao>=DATE '2026-06-02' AND data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(id_imovel,'-','') ORDER BY data_extracao DESC)=1),p AS (SELECT DISTINCT ano_emissao,id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao BETWEEN 2013 AND 2026 AND id_car IS NOT NULL AND TRIM(id_car)!=''),x AS (SELECT p.ano_emissao,p.id_car_norm,c.id_municipio FROM p JOIN car c USING(id_car_norm) WHERE c.area<0.1),z AS (SELECT id_municipio,id_car_norm,COUNT(DISTINCT ano_emissao) anos,MIN(ano_emissao) primeiro_ano,MAX(ano_emissao) ultimo_ano FROM x GROUP BY 1,2) SELECT id_municipio,COUNT(*) imoveis_micro,COUNTIF(anos>1) imoveis_repetidos_em_varios_anos,MAX(anos) max_anos_por_imovel,MIN(primeiro_ano) primeiro_ano_micro,MAX(ultimo_ano) ultimo_ano_micro FROM z GROUP BY id_municipio ORDER BY id_municipio